using System.Text.Json;using QualityReporter.CSharp;using QualityReporter.CSharp.Analysis;using QualityReporter.CSharp.Coverage;using QualityReporter.CSharp.Git;using QualityReporter.CSharp.Metrics;using QualityReporter.CSharp.Reporting;
if(args.Length==0||args[0]!="analyze"){Console.Error.WriteLine("Usage: quality-csharp analyze --solution <path> --output <path> [--coverage file] [--analyzer file] [--config file] [--baseline file] [--markdown file] [--since 180d]");return 2;}var o=new Dictionary<string,string>();for(var i=1;i<args.Length;i+=2)if(i+1<args.Length)o[args[i]]=args[i+1];if(!o.TryGetValue("--solution",out var solution)||!o.TryGetValue("--output",out var output)){Console.Error.WriteLine("--solution and --output are required");return 2;}if(!File.Exists(solution)){Console.Error.WriteLine($"Solution not found: {solution}");return 2;}try{var root=Path.GetDirectoryName(Path.GetFullPath(solution))!;var cfg=o.TryGetValue("--config",out var cp)?JsonSerializer.Deserialize<Config>(File.ReadAllText(cp),new JsonSerializerOptions{PropertyNameCaseInsensitive=true})??new():new Config();var days=o.TryGetValue("--since",out var since)&&int.TryParse(since.TrimEnd('d'),out var d)?d:cfg.HistoryDays;var git=new GitCommandRunner();git.Run(root,"rev-parse","--is-inside-work-tree");var (history,couplings)=new GitHistoryAnalyzer(git).Analyze(root,days,cfg);var files=Directory.EnumerateFiles(root,"*.cs",SearchOption.AllDirectories).Where(p=>!cfg.Exclude.Any(e=>Glob(p[root.Length..].TrimStart('/'),e))).Select(p=>(abs:p,rel:Path.GetRelativePath(root,p).Replace('\\','/'))).ToList();var metrics=new CodeMetricsAnalyzer();var results=files.Select(f=>{var(m,fn)=metrics.Analyze(f.abs);return new FileResult{Path=f.rel,Metrics=m,Functions=fn,History=history.GetValueOrDefault(f.rel)??new(),Couplings=couplings.Where(x=>x.File==f.rel).ToList()};}).ToList();var report=new Report{Repository=new{branch=git.Run(root,"branch","--show-current").Trim(),commit=git.Run(root,"rev-parse","HEAD").Trim()},Files=results};if(o.TryGetValue("--coverage",out var cov)&&File.Exists(cov)){var data=CoberturaParser.Parse(cov);foreach(var f in results)if(data.TryGetValue(f.Path,out var c))(f.Metrics.LineCoverage,f.Metrics.BranchCoverage)=c;}else report.Warnings.Add("Coverage: Not Available");if(o.TryGetValue("--analyzer",out var an)&&File.Exists(an))foreach(var i in AnalyzerResultParser.Parse(an)){var f=results.FirstOrDefault(x=>i.File.EndsWith(x.Path));if(f!=null){if(i.Severity=="error")f.Metrics.Issues.Error++;else if(i.Severity=="warning")f.Metrics.Issues.Warning++;else f.Metrics.Issues.Info++;}}else report.Warnings.Add("Analyzer results: Not Available");RiskCalculator.Calculate(results,cfg.RiskWeights);report.Summary=new{files=results.Count,overallRisk=results.Count==0?0:results.Average(x=>x.Risk.Score),hotspotCount=results.Count(x=>x.Risk.Score>=60),criticalCount=results.Count(x=>x.Risk.Level=="critical"),averageCoverage=results.Where(x=>x.Metrics.LineCoverage.HasValue).Select(x=>x.Metrics.LineCoverage).DefaultIfEmpty().Average(),averageComplexity=results.Count==0?0:results.Average(x=>x.Metrics.Complexity),highComplexityFunctionCount=results.SelectMany(x=>x.Functions).Count(x=>x.Complexity>=15)};if(o.TryGetValue("--baseline",out var baseline)&&File.Exists(baseline))report.Trend=BaselineComparer.Compare(report,ReportWriter.Read(baseline));ReportWriter.WriteJson(report,output);if(o.TryGetValue("--markdown",out var md))ReportWriter.WriteMarkdown(report,md);Console.WriteLine($"Analyzed {results.Count} C# files; report: {output}");return 0;}catch(Exception ex){Console.Error.WriteLine(ex.Message);return 1;}
static bool Glob(string path,string pattern){path=path.Replace('\\','/');var p=System.Text.RegularExpressions.Regex.Escape(pattern).Replace("\\*\\*",".*").Replace("\\*","[^/]*");return System.Text.RegularExpressions.Regex.IsMatch("/"+path,"^/?"+p+"$",System.Text.RegularExpressions.RegexOptions.IgnoreCase);}
